WITH filtered AS (SELECT *, DATE_TRUNC('month', started_at) AS started_at_period FROM sessions WHERE device <> 'mobile') SELECT id, country, started_at_period, LAST_VALUE(country) IGNORE NULLS OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY customer_id, country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser FROM filtered
